INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(650, 'difference', '/ˈdɪfərəns/', 'noun', '{"zh-TW":["差異；不同"],"en":["the way in which things are not the same"]}', NULL, 'make a difference / tell the difference', '[{"en":"Can you tell the difference?","zh-TW":"你能分辨出差異嗎？"},{"en":"Small actions can make a big difference.","zh-TW":"小小的行動可以帶來很大的改變。"}]', '{"adjective":"different","verb":"differ","adverb":"differently"}', NULL, 4, 650),
(651, 'difficult', '/ˈdɪfɪkəlt/', 'adjective', '{"zh-TW":["困難的"],"en":["not easy to do or understand"]}', NULL, 'difficult question / difficult situation', '[{"en":"The exam was very difficult.","zh-TW":"考試非常困難。"},{"en":"She''s in a difficult situation.","zh-TW":"她處於困難的處境中。"}]', '{"noun":"difficulty"}', NULL, 3, 651),
(652, 'dig', '/dɪɡ/', 'verb', '{"zh-TW":["挖掘"],"en":["to make a hole in the ground"]}', NULL, 'dig a hole / dig up', '[{"en":"The dog dug a hole in the garden.","zh-TW":"狗在花園裡挖了一個洞。"},{"en":"They dug up some old coins.","zh-TW":"他們挖出了一些舊硬幣。"}]', NULL, NULL, 1, 652),
(653, 'digital', '/ˈdɪdʒɪtəl/', 'adjective', '{"zh-TW":["數位的；數碼的","數位的"],"en":["relating to computer technology or electronic data","using electronic technology"]}', NULL, 'digital transformation; digital camera / digital transformation', '[{"en":"The company is undergoing a digital transformation.","zh-TW":"公司正在進行數位轉型。"},{"en":"Digital marketing is essential today.","zh-TW":"數位行銷在今天是必不可少的。"},{"en":"We live in the digital age.","zh-TW":"我們生活在數位時代。"},{"en":"The company is undergoing digital transformation.","zh-TW":"公司正在進行數位轉型。"}]', '{"noun":"digitization","adjective":"digital","adverb":"digitally","verb":"digitize"}', NULL, 3, 653),
(654, 'diligent', '/ˈdɪlɪdʒənt/', 'adjective', '{"zh-TW":["勤勉的；勤奮的"],"en":["showing care and effort in one''s work"]}', NULL, 'diligent worker/student', '[{"en":"She is a diligent employee who always meets her goals.","zh-TW":"她是一位勤勉的員工，總是達成目標。"},{"en":"Diligent research led to the breakthrough.","zh-TW":"勤勉的研究促成了突破。"}]', '{"noun":"diligence","adjective":"diligent","adverb":"diligently"}', NULL, 3, 654),
(655, 'dimension', '/daɪˈmenʃn/', 'noun', '{"zh-TW":["尺寸；維度；層面"],"en":["a measurable extent","an aspect of something"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"mens","meaning":"measure (測量)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"分開測量的各面向，即「維度」。"}', 'new dimension / three-dimensional', '[{"en":"The room''s dimensions are 5 by 4 meters.","zh-TW":"房間的尺寸是5乘4公尺。"},{"en":"This adds a new dimension to the problem.","zh-TW":"這為問題增添了新的層面。"}]', '{"adjective":"dimensional"}', NULL, 3, 655),
(656, 'diminish', '/dɪˈmɪnɪʃ/', 'verb', '{"zh-TW":["減少；縮小","減少；削弱"],"en":["to make or become less"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"min","meaning":"small (小)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使變小，即「減少」。"}', 'diminish in value/importance; diminish in value / diminishing returns', '[{"en":"The value of the investment has diminished.","zh-TW":"投資的價值已經減少。"},{"en":"Nothing can diminish her achievements.","zh-TW":"沒有什麼能削弱她的成就。"},{"en":"His influence has diminished over the years.","zh-TW":"他的影響力逐年減弱。"}]', '{"verb":"diminish","adjective":"diminished"}', NULL, 3, 656),
(657, 'dinner', '/ˈdɪnər/', 'noun', '{"zh-TW":["晚餐"],"en":["the main meal of the day, usually in the evening","the main meal of the day"]}', NULL, 'business dinner / dinner party; dinner party / have dinner', '[{"en":"We have a business dinner tonight.","zh-TW":"我們今晚有商務晚餐。"},{"en":"Shall we go out for dinner?","zh-TW":"我們出去吃晚餐好嗎？"},{"en":"What''s for dinner tonight?","zh-TW":"今晚晚餐吃什麼？"},{"en":"Let''s have dinner together.","zh-TW":"一起吃晚餐吧。"}]', '{"noun":"dinner"}', NULL, 2, 657),
(658, 'diploma', '/dɪˈploʊmə/', 'noun', '{"zh-TW":["文憑；畢業證書"],"en":["a certificate awarded after completing a course"]}', NULL, 'high school diploma / diploma program', '[{"en":"He received his diploma at graduation.","zh-TW":"他在畢業典禮上拿到了文憑。"},{"en":"A diploma is required for this job.","zh-TW":"這份工作需要文憑。"}]', NULL, NULL, 3, 658),
(659, 'diplomatic', '/ˌdɪpləˈmætɪk/', 'adjective', '{"zh-TW":["外交的；圓融的"],"en":["relating to managing international relations"]}', NULL, 'diplomatic relations / diplomatic immunity', '[{"en":"They broke off diplomatic relations.","zh-TW":"他們斷絕了外交關係。"},{"en":"She handled the situation diplomatically.","zh-TW":"她圓融地處理了這個情況。"}]', '{"noun":"diplomacy","noun2":"diplomat"}', NULL, 4, 659),
(660, 'direct', '/dɪˈrekt/', 'verb / adjective', '{"zh-TW":["指導；直接的","直接的"],"en":["to manage; without anything in between","going straight without stopping"]}', NULL, 'direct contact/access; direct flight / direct contact', '[{"en":"She directs the marketing department.","zh-TW":"她指導行銷部門。"},{"en":"Is there a direct flight to Tokyo?","zh-TW":"有直飛東京的航班嗎？"},{"en":"He gave a direct answer.","zh-TW":"他給了一個直接的回答。"}]', '{"noun":"direction/director","verb":"direct","adjective":"direct","adverb":"directly","noun2":"director"}', NULL, 2, 660),
(661, 'dirty', '/ˈdɜːrti/', 'adjective', '{"zh-TW":["髒的"],"en":["not clean; covered in unwanted substances","not clean"]}', NULL, 'dirty work / get dirty; dirty hands / dirty work', '[{"en":"Someone has to do the dirty work.","zh-TW":"總得有人做苦差事。"},{"en":"The warehouse floor was dirty.","zh-TW":"倉庫地板很髒。"},{"en":"Your hands are dirty.","zh-TW":"你的手很髒。"},{"en":"Nobody wants to do the dirty work.","zh-TW":"沒人想做髒活。"}]', '{"adjective":"dirty","verb":"dirty","noun":"dirt"}', NULL, 2, 661),
(662, 'disability', '/ˌdɪsəˈbɪləti/', 'noun', '{"zh-TW":["殘疾；障礙"],"en":["a physical or mental condition that limits ability"]}', NULL, 'learning/physical disability', '[{"en":"The company provides support for employees with disabilities.","zh-TW":"公司為有殘疾的員工提供支援。"},{"en":"Disability benefits are available for those who qualify.","zh-TW":"符合資格者可獲得殘疾福利。"}]', '{"noun":"disability","verb":"disable","adjective":"disabled"}', NULL, 4, 662),
(663, 'disappear', '/ˌdɪsəˈpɪr/', 'verb', '{"zh-TW":["消失"],"en":["to become impossible to see"]}', NULL, 'disappear from view / disappear without a trace', '[{"en":"The sun disappeared behind the clouds.","zh-TW":"太陽消失在雲後面。"},{"en":"He disappeared without a trace.","zh-TW":"他消失得無影無蹤。"}]', '{"noun":"disappearance"}', NULL, 3, 663),
(664, 'disappoint', '/ˌdɪsəˈpɔɪnt/', 'verb', '{"zh-TW":["使失望"],"en":["to fail to fulfill the expectations of"]}', NULL, 'deeply disappointed', '[{"en":"The results disappointed the investors.","zh-TW":"結果讓投資者失望了。"},{"en":"I''m disappointed with the service quality.","zh-TW":"我對服務品質感到失望。"}]', '{"noun":"disappointment","verb":"disappoint","adjective":"disappointing/disappointed"}', NULL, 4, 664),
(665, 'disappointed', '/ˌdɪsəˈpɔɪntɪd/', 'adjective', '{"zh-TW":["失望的"],"en":["sad because something was not as good as expected"]}', '{"prefix":{"text":"dis-","meaning":"not (不)"},"root":{"text":"appoint","meaning":"arrange (安排)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"事情沒有按安排進行的感受，即「失望的」。"}', 'deeply disappointed / disappointed with', '[{"en":"She was disappointed with the test results.","zh-TW":"她對考試成績感到失望。"},{"en":"Fans were disappointed by the team''s performance.","zh-TW":"球迷對球隊的表現感到失望。"}]', '{"noun":"disappointment","adjective":"disappointing"}', NULL, 4, 665),
(666, 'disaster', '/dɪˈzæstər/', 'noun', '{"zh-TW":["災難"],"en":["a sudden event causing great damage"]}', '{"prefix":{"text":"dis-","meaning":"bad (不好)"},"root":{"text":"aster","meaning":"star (星)"},"logic":"星象不吉（古人認為災難與凶星有關）。"}', 'natural disaster / disaster relief / disaster management', '[{"en":"The earthquake was a major natural disaster.","zh-TW":"地震是一場重大自然災難。"},{"en":"Disaster relief teams were sent immediately.","zh-TW":"救災隊伍被立即派遣。"}]', '{"adjective":"disastrous"}', NULL, 3, 666),
(667, 'disbursement', '/dɪsˈbɜːrsmənt/', 'noun', '{"zh-TW":["支出；支付"],"en":["the payment of money from a fund"]}', NULL, 'cash disbursement / loan disbursement', '[{"en":"Loan disbursement will occur within 5 days.","zh-TW":"貸款將在5天內撥付。"},{"en":"Track all cash disbursements carefully.","zh-TW":"仔細追蹤所有現金支出。"}]', '{"noun":"disbursement","verb":"disburse"}', NULL, 4, 667),
(668, 'discard', '/dɪˈskɑːrd/', 'verb', '{"zh-TW":["丟棄；拋棄"],"en":["to get rid of something no longer useful"]}', NULL, 'discard old files', '[{"en":"Please discard any outdated documents.","zh-TW":"請丟棄任何過時的文件。"},{"en":"The idea was discarded as impractical.","zh-TW":"這個想法因不切實際而被拋棄。"}]', '{"verb":"discard"}', NULL, 3, 668),
(669, 'discipline', '/ˈdɪsəplɪn/', 'noun / verb', '{"zh-TW":["紀律；學科"],"en":["the practice of training people to obey rules","controlled behavior; a branch of knowledge","a branch of knowledge"]}', '{"root":{"text":"disciple","meaning":"learner (學習者)"},"logic":"學習者應遵守的規範，即「紀律」。"}', 'maintain discipline; self-discipline / academic discipline; self-discipline / academic discipline / maintain discipline', '[{"en":"Good discipline is essential in the workplace.","zh-TW":"良好的紀律在職場是必要的。"},{"en":"Marketing is a rapidly changing discipline.","zh-TW":"行銷是一個快速變化的學科。"},{"en":"Success requires discipline.","zh-TW":"成功需要紀律。"},{"en":"Biology is a scientific discipline.","zh-TW":"生物學是一門科學學科。"},{"en":"Success requires discipline and hard work.","zh-TW":"成功需要紀律和努力。"},{"en":"Psychology is a fascinating discipline.","zh-TW":"心理學是一門迷人的學科。"}]', '{"noun":"discipline","verb":"discipline","adjective":"disciplined"}', NULL, 4, 669),
(670, 'disclose', '/dɪˈskloʊz/', 'verb', '{"zh-TW":["揭露；公開"],"en":["to make information known publicly"]}', NULL, 'disclose information', '[{"en":"The company refused to disclose its financial data.","zh-TW":"公司拒絕公開其財務數據。"},{"en":"He disclosed the details of the agreement.","zh-TW":"他揭露了協議的細節。"}]', '{"noun":"disclosure","verb":"disclose"}', NULL, 3, 670),
(671, 'discount', '/ˈdɪskaʊnt/', 'noun / verb', '{"zh-TW":["折扣；打折"],"en":["a reduction in the usual price"]}', NULL, 'offer/give a discount', '[{"en":"We offer a 20% discount for bulk orders.","zh-TW":"我們對大量訂單提供八折優惠。"},{"en":"The store discounted all winter items.","zh-TW":"商店對所有冬季商品打折。"}]', '{"noun":"discount","verb":"discount","adjective":"discounted"}', NULL, 3, 671),
(672, 'discover', '/dɪˈskʌvər/', 'verb', '{"zh-TW":["發現"],"en":["to find something for the first time"]}', NULL, 'discover a solution; discover a new species / discover the truth', '[{"en":"Scientists discovered a new treatment.","zh-TW":"科學家發現了一種新療法。"},{"en":"She discovered an error in the report.","zh-TW":"她在報告中發現了一個錯誤。"},{"en":"Columbus discovered America in 1492.","zh-TW":"哥倫布在1492年發現了美洲。"},{"en":"She discovered the truth about her past.","zh-TW":"她發現了關於她過去的真相。"}]', '{"noun":"discovery","verb":"discover"}', NULL, 3, 672),
(673, 'discretion', '/dɪˈskreʃən/', 'noun', '{"zh-TW":["判斷力；酌情權"],"en":["the freedom to decide what should be done"]}', NULL, 'at one''s discretion', '[{"en":"Use your own discretion when handling complaints.","zh-TW":"處理投訴時請自行判斷。"},{"en":"Bonuses are awarded at management''s discretion.","zh-TW":"獎金由管理層酌情發放。"}]', '{"noun":"discretion","adjective":"discreet/discretionary"}', NULL, 4, 673),
(674, 'discriminate', '/dɪˈskrɪmɪneɪt/', 'verb', '{"zh-TW":["歧視；區別"],"en":["to treat unfairly based on prejudice"]}', NULL, 'discriminate against', '[{"en":"It is illegal to discriminate against employees based on age.","zh-TW":"基於年齡歧視員工是違法的。"},{"en":"Can you discriminate between the two options?","zh-TW":"你能區分這兩個選項嗎？"}]', '{"noun":"discrimination","verb":"discriminate","adjective":"discriminatory"}', NULL, 4, 674),
(675, 'discrimination', '/dɪˌskrɪmɪˈneɪʃn/', 'noun', '{"zh-TW":["歧視；辨別"],"en":["unjust treatment based on race, age, or gender"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"crimin","meaning":"separate (區分)"},"suffix":{"text":"-ation","meaning":"act of (行為)"},"logic":"把人分開區別對待，即「歧視」。"}', 'racial discrimination / gender discrimination', '[{"en":"Discrimination based on age is illegal.","zh-TW":"年齡歧視是違法的。"},{"en":"The company has a strict anti-discrimination policy.","zh-TW":"公司有嚴格的反歧視政策。"}]', '{"verb":"discriminate","adjective":"discriminatory"}', NULL, 5, 675),
(676, 'discuss', '/dɪˈskʌs/', 'verb', '{"zh-TW":["討論"],"en":["to talk about something in detail","to talk about something with others"]}', NULL, 'discuss the matter/issue; discuss a topic / discuss the matter', '[{"en":"We need to discuss the budget proposal.","zh-TW":"我們需要討論預算提案。"},{"en":"The team discussed several options.","zh-TW":"團隊討論了幾個方案。"},{"en":"Let''s discuss this later.","zh-TW":"我們稍後再討論這件事。"},{"en":"They discussed the proposal at the meeting.","zh-TW":"他們在會議上討論了提案。"}]', '{"noun":"discussion","verb":"discuss"}', NULL, 3, 676),
(677, 'dismiss', '/dɪˈsmɪs/', 'verb', '{"zh-TW":["解僱；駁回","解僱；駁回；不理會"],"en":["to remove from a job; to reject","to send away","to refuse to consider"]}', '{"prefix":{"text":"dis-","meaning":"away (離開)"},"root":{"text":"miss","meaning":"send (送)"},"logic":"把人送走，即「解僱」或「不理會」。"}', 'dismiss an employee/idea; dismiss an employee / dismiss the idea / dismiss the case', '[{"en":"He was dismissed for misconduct.","zh-TW":"他因行為不當被解僱。"},{"en":"The court dismissed the case.","zh-TW":"法院駁回了此案。"},{"en":"The manager dismissed the complaint.","zh-TW":"經理駁回了投訴。"},{"en":"You shouldn''t dismiss his suggestions so quickly.","zh-TW":"你不應該這麼快就否定他的建議。"}]', '{"noun":"dismissal","verb":"dismiss"}', NULL, 3, 677),
(678, 'disorder', '/dɪsˈɔːrdər/', 'noun', '{"zh-TW":["失調；混亂"],"en":["a state of confusion","a medical condition"]}', '{"prefix":{"text":"dis-","meaning":"not (不)"},"root":{"text":"order","meaning":"order (秩序)"},"logic":"沒有秩序，即「混亂」。"}', 'mental disorder / eating disorder / in disorder', '[{"en":"The room was in complete disorder.","zh-TW":"房間完全一片混亂。"},{"en":"She was diagnosed with an anxiety disorder.","zh-TW":"她被診斷出焦慮症。"}]', '{"adjective":"disordered","adjective2":"disorderly"}', NULL, 3, 678),
(679, 'dispatch', '/dɪˈspætʃ/', 'verb / noun', '{"zh-TW":["派遣；發送"],"en":["to send off to a destination"]}', NULL, 'dispatch goods/a team', '[{"en":"The order was dispatched this morning.","zh-TW":"訂單今早已發出。"},{"en":"A repair team was dispatched immediately.","zh-TW":"維修團隊立即被派遣。"}]', '{"noun":"dispatch","verb":"dispatch"}', NULL, 3, 679),
(680, 'display', '/dɪˈspleɪ/', 'verb / noun', '{"zh-TW":["展示；顯示","展示；陳列"],"en":["to show something publicly","an arrangement of items for public viewing"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"play","meaning":"fold (展開)"},"logic":"展開來讓人看，即「展示」。"}', 'on display; on display / window display', '[{"en":"The products are displayed in the window.","zh-TW":"產品展示在櫥窗中。"},{"en":"The artwork is on display until March.","zh-TW":"藝術品展出至三月。"},{"en":"The new products are on display in the window.","zh-TW":"新產品正在櫥窗展示。"},{"en":"The museum has an impressive display of artifacts.","zh-TW":"博物館有令人印象深刻的文物展示。"}]', '{"noun":"display","verb":"display"}', NULL, 3, 680),
(681, 'disposal', '/dɪˈspoʊzl/', 'noun', '{"zh-TW":["處理；處置"],"en":["the act of getting rid of something"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"pos","meaning":"put (放置)"},"suffix":{"text":"-al","meaning":"act of (行為)"},"logic":"把東西放到一邊去，即「處置」。"}', 'waste disposal / at one''s disposal', '[{"en":"Proper waste disposal protects the environment.","zh-TW":"適當的廢物處理保護環境。"},{"en":"I am at your disposal.","zh-TW":"我隨時為您效勞。"}]', '{"verb":"dispose","adjective":"disposable"}', NULL, 3, 681),
(682, 'dispose', '/dɪˈspoʊz/', 'verb', '{"zh-TW":["處理；丟棄"],"en":["to get rid of; to arrange"]}', NULL, 'dispose of waste', '[{"en":"Please dispose of waste properly.","zh-TW":"請正確處理廢棄物。"},{"en":"The company disposed of its old equipment.","zh-TW":"公司處理了舊設備。"}]', '{"noun":"disposal/disposition","verb":"dispose","adjective":"disposable"}', NULL, 3, 682),
(683, 'dispute', '/dɪˈspjuːt/', 'noun / verb', '{"zh-TW":["爭議；爭論","爭議；糾紛"],"en":["a disagreement or argument"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"pute","meaning":"think (思考)"},"logic":"想法分歧，即「爭議」。"}', 'resolve/settle a dispute; legal dispute / labor dispute / settle a dispute', '[{"en":"The dispute was settled out of court.","zh-TW":"爭議在庭外解決了。"},{"en":"They disputed the accuracy of the report.","zh-TW":"他們對報告的準確性提出異議。"},{"en":"The labor dispute lasted several weeks.","zh-TW":"勞資糾紛持續了好幾週。"},{"en":"They settled the dispute out of court.","zh-TW":"他們在庭外解決了糾紛。"}]', '{"noun":"dispute","verb":"dispute"}', NULL, 3, 683),
(684, 'disrupt', '/dɪsˈrʌpt/', 'verb', '{"zh-TW":["擾亂；中斷"],"en":["to interrupt the normal course of"]}', NULL, 'disrupt operations/services', '[{"en":"The strike disrupted public transportation.","zh-TW":"罷工擾亂了公共交通。"},{"en":"New technology is disrupting traditional industries.","zh-TW":"新技術正在顛覆傳統產業。"}]', '{"noun":"disruption","verb":"disrupt","adjective":"disruptive"}', NULL, 3, 684),
(685, 'dissertation', '/ˌdɪsərˈteɪʃən/', 'noun', '{"zh-TW":["論文；學位論文"],"en":["a long essay on a subject for a university degree"]}', NULL, 'doctoral dissertation / write a dissertation', '[{"en":"She wrote her dissertation on market behavior.","zh-TW":"她的論文主題是市場行為。"},{"en":"His dissertation was published as a book.","zh-TW":"他的論文出版成書了。"}]', '{"noun":"dissertation"}', NULL, 4, 685),
(686, 'dissolve', '/dɪˈzɑːlv/', 'verb', '{"zh-TW":["解散；溶解"],"en":["to officially end; to mix into a liquid"]}', NULL, 'dissolve a partnership', '[{"en":"The partnership was dissolved last year.","zh-TW":"合夥關係去年解散了。"},{"en":"Sugar dissolves in water.","zh-TW":"糖溶解在水中。"}]', '{"noun":"dissolution","verb":"dissolve"}', NULL, 3, 686),
(687, 'distance', '/ˈdɪstəns/', 'noun', '{"zh-TW":["距離"],"en":["the space between two points"]}', NULL, 'long distance / keep one''s distance', '[{"en":"What''s the distance to the airport?","zh-TW":"到機場有多遠？"},{"en":"Keep your distance from the edge.","zh-TW":"離邊緣遠一點。"}]', '{"adjective":"distant"}', NULL, 3, 687),
(688, 'distinct', '/dɪˈstɪŋkt/', 'adjective', '{"zh-TW":["明顯的；不同的","不同的；明顯的"],"en":["clearly different or separate"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"tinct","meaning":"prick/mark (刺/標記)"},"logic":"被標記而分開的，即「不同的」。"}', 'distinct advantage/difference; distinct difference / distinct advantage / distinct from', '[{"en":"There is a distinct difference between the two.","zh-TW":"兩者之間有明顯的區別。"},{"en":"The product has a distinct advantage.","zh-TW":"該產品有明顯的優勢。"},{"en":"The two species are distinct from each other.","zh-TW":"這兩個物種彼此不同。"},{"en":"There is a distinct possibility of rain.","zh-TW":"有明顯下雨的可能性。"}]', '{"noun":"distinction","adjective":"distinct/distinctive","adverb":"distinctly"}', NULL, 3, 688),
(689, 'distinguish', '/dɪˈstɪŋɡwɪʃ/', 'verb', '{"zh-TW":["區分；辨別"],"en":["to recognize differences between things"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"sting","meaning":"prick/mark (刺/標記)"},"suffix":{"text":"-uish","meaning":"make (使)"},"logic":"使標記分開，即「區分」。"}', 'distinguish between/from; distinguish between / distinguish oneself', '[{"en":"It''s hard to distinguish the original from the copy.","zh-TW":"很難區分原件和副本。"},{"en":"What distinguishes our brand from competitors?","zh-TW":"什麼使我們的品牌與競爭對手不同？"},{"en":"It is important to distinguish fact from opinion.","zh-TW":"區分事實和意見很重要。"},{"en":"She distinguished herself in her field.","zh-TW":"她在自己的領域中出類拔萃。"}]', '{"adjective":"distinguished","verb":"distinguish","adjective2":"distinguishable"}', NULL, 4, 689),
(690, 'distribute', '/dɪˈstrɪbjuːt/', 'verb', '{"zh-TW":["分配；分發"],"en":["to give shares of something to several people"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"tribute","meaning":"assign (分派)"},"logic":"分開指派給各人，即「分配」。"}', 'distribute evenly/widely; distribute evenly / distribute resources', '[{"en":"The company distributes products worldwide.","zh-TW":"公司在全球分銷產品。"},{"en":"Profits are distributed among shareholders.","zh-TW":"利潤分配給股東。"},{"en":"The charity distributes food to the homeless.","zh-TW":"慈善機構向無家可歸者分發食物。"}]', '{"noun":"distribution/distributor","verb":"distribute","noun2":"distributor"}', NULL, 4, 690),
(691, 'disturb', '/dɪˈstɜːrb/', 'verb', '{"zh-TW":["打擾；使不安"],"en":["to interrupt or cause concern"]}', '{"prefix":{"text":"dis-","meaning":"thoroughly (徹底)"},"root":{"text":"turb","meaning":"confuse (混亂)"},"logic":"徹底使其混亂，即「打擾」。"}', 'do not disturb / disturb the peace', '[{"en":"Please do not disturb me while I''m working.","zh-TW":"我工作時請不要打擾我。"},{"en":"The news disturbed her deeply.","zh-TW":"這個消息讓她深感不安。"}]', '{"noun":"disturbance","adjective":"disturbing"}', NULL, 3, 691),
(692, 'diverse', '/daɪˈvɜːrs/', 'adjective', '{"zh-TW":["多樣的；多元的","多樣的；不同的"],"en":["showing great variety","showing a great deal of variety"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"verse","meaning":"turn (轉)"},"logic":"朝不同方向轉的，即「多樣的」。"}', 'diverse workforce/portfolio; diverse population / culturally diverse', '[{"en":"We have a diverse team from many backgrounds.","zh-TW":"我們有來自不同背景的多元團隊。"},{"en":"A diverse portfolio reduces risk.","zh-TW":"多元化的投資組合可以降低風險。"},{"en":"The city has a diverse population.","zh-TW":"這座城市有多元的人口。"},{"en":"We need a more diverse team.","zh-TW":"我們需要一個更多元的團隊。"}]', '{"noun":"diversity/diversification","verb":"diversify","adjective":"diverse"}', NULL, 3, 692),
(693, 'diversification', '/daɪˌvɜːrsɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["多元化"],"en":["the process of expanding into different areas"]}', NULL, 'portfolio diversification / market diversification', '[{"en":"Diversification reduces investment risk.","zh-TW":"多元化降低投資風險。"},{"en":"Market diversification is key to growth.","zh-TW":"市場多元化是成長的關鍵。"}]', '{"noun":"diversification","verb":"diversify","adjective":"diversified"}', NULL, 5, 693),
(694, 'divide', '/dɪˈvaɪd/', 'verb', '{"zh-TW":["劃分；除以"],"en":["to separate into parts"]}', NULL, 'divide into/among', '[{"en":"The project is divided into three phases.","zh-TW":"該項目分為三個階段。"},{"en":"Profits were divided equally among partners.","zh-TW":"利潤在合夥人之間平均分配。"}]', '{"noun":"division","verb":"divide"}', NULL, 2, 694),
(695, 'doctrine', '/ˈdɒktrɪn/', 'noun', '{"zh-TW":["教義；學說"],"en":["a set of beliefs or principles held by a group"]}', '{"root":{"text":"doct","meaning":"teach (教導)"},"suffix":{"text":"-rine","meaning":"thing (事物)"},"logic":"被教導的東西，即「教義」。"}', 'political doctrine / legal doctrine', '[{"en":"The party changed its economic doctrine.","zh-TW":"該黨改變了其經濟學說。"},{"en":"This is a fundamental doctrine of the religion.","zh-TW":"這是該宗教的基本教義。"}]', NULL, NULL, 3, 695),
(696, 'document', '/ˈdɑːkjumənt/', 'noun / verb', '{"zh-TW":["文件；記錄"],"en":["a written or printed paper; to record"]}', NULL, 'official document', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要的文件。"},{"en":"Everything must be documented carefully.","zh-TW":"一切都必須仔細記錄。"}]', '{"noun":"document/documentation","verb":"document"}', NULL, 3, 696),
(697, 'documentary', '/ˌdɒkjuˈmɛntəri/', 'noun', '{"zh-TW":["紀錄片"],"en":["a film based on real events"]}', NULL, 'nature documentary / documentary film', '[{"en":"I watched a documentary about climate change.","zh-TW":"我看了一部關於氣候變遷的紀錄片。"},{"en":"She directed an award-winning documentary.","zh-TW":"她執導了一部獲獎紀錄片。"}]', NULL, NULL, 4, 697),
(698, 'dog', '/dɒɡ/', 'noun', '{"zh-TW":["狗"],"en":["a common domestic animal"]}', NULL, 'guide dog / dog-eat-dog', '[{"en":"It is a dog-eat-dog world in sales.","zh-TW":"銷售業是個競爭激烈的世界。"},{"en":"Some offices allow employees to bring dogs.","zh-TW":"有些辦公室允許員工帶狗。"}]', '{"noun":"dog"}', NULL, 1, 698),
(699, 'dollar', '/ˈdɒlər/', 'noun', '{"zh-TW":["美元"],"en":["the basic unit of money in the US"]}', NULL, 'dollar sign / dollar amount', '[{"en":"The total comes to 500 dollars.","zh-TW":"總共是500美元。"},{"en":"The dollar weakened against the euro.","zh-TW":"美元對歐元貶值了。"}]', '{"noun":"dollar"}', NULL, 2, 699);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(700, 'domain', '/doʊˈmeɪn/', 'noun', '{"zh-TW":["網域；領域","領域；域"],"en":["an area of activity; a website address","an area of knowledge or activity","an internet address"]}', '{"root":{"text":"domin","meaning":"lord/master (主人)"},"logic":"主人管轄的範圍，即「領域」。"}', 'domain name / public domain; public domain / domain name / domain knowledge', '[{"en":"Register a domain name for your website.","zh-TW":"為你的網站註冊一個網域名稱。"},{"en":"That''s outside my domain of expertise.","zh-TW":"那不在我的專業領域內。"},{"en":"This issue falls outside my domain of expertise.","zh-TW":"這個問題不在我的專業領域範圍內。"},{"en":"She registered a new domain name for her website.","zh-TW":"她為網站註冊了一個新網域名稱。"}]', NULL, NULL, 2, 700),
(701, 'domestic', '/dəˈmestɪk/', 'adjective', '{"zh-TW":["國內的；家庭的"],"en":["relating to one''s own country; relating to home"]}', NULL, 'domestic market/flight', '[{"en":"Domestic sales increased by 15%.","zh-TW":"國內銷售額增長了15%。"},{"en":"The airline offers both domestic and international flights.","zh-TW":"該航空公司提供國內和國際航班。"}]', '{"adjective":"domestic","adverb":"domestically"}', NULL, 3, 701),
(702, 'dominate', '/ˈdɑːmɪneɪt/', 'verb', '{"zh-TW":["主導；支配","主宰；支配"],"en":["to have control or influence over","to have a commanding influence over"]}', '{"root":{"text":"domin","meaning":"lord/master (主人)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使自己成為主人，即「支配」。"}', 'dominate the market; dominate the market / dominate the conversation', '[{"en":"The company dominates the smartphone market.","zh-TW":"該公司主導智慧型手機市場。"},{"en":"One topic dominated the meeting.","zh-TW":"一個話題主導了會議。"},{"en":"The company dominates the smartphone market.","zh-TW":"這家公司主宰了智慧型手機市場。"},{"en":"He tends to dominate conversations.","zh-TW":"他往往主導談話。"}]', '{"noun":"dominance","verb":"dominate","adjective":"dominant","noun2":"dominance"}', NULL, 3, 702),
(703, 'donate', '/ˈdoʊneɪt/', 'verb', '{"zh-TW":["捐贈；捐獻","捐贈"],"en":["to give money or goods to a cause","to give money or goods for a good cause"]}', '{"root":{"text":"don","meaning":"give (給予)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使給予，即「捐贈」。"}', 'donate money/blood; donate money / donate blood / donate to charity', '[{"en":"She donated $10,000 to charity.","zh-TW":"她捐了一萬美元給慈善機構。"},{"en":"Many employees donated blood.","zh-TW":"許多員工捐了血。"},{"en":"She donated $1000 to the charity.","zh-TW":"她捐了1000美元給慈善機構。"},{"en":"Would you like to donate blood?","zh-TW":"你願意捐血嗎？"}]', '{"noun":"donation/donor","verb":"donate","noun2":"donor"}', NULL, 2, 703),
(704, 'door', '/dɔːr/', 'noun', '{"zh-TW":["門"],"en":["a movable barrier at the entrance"]}', NULL, 'next door / open door policy', '[{"en":"Our office has an open door policy.","zh-TW":"我們辦公室有開放門戶政策。"},{"en":"Please close the door behind you.","zh-TW":"請隨手關門。"}]', '{"noun":"door","noun2":"doorway"}', NULL, 1, 704),
(705, 'dormitory', '/ˈdɔːrmɪtɔːri/', 'noun', '{"zh-TW":["宿舍"],"en":["a building where students live at school"]}', NULL, 'dormitory room / student dormitory', '[{"en":"First-year students live in the dormitory.","zh-TW":"大一學生住在宿舍。"},{"en":"The dormitory has a shared kitchen.","zh-TW":"宿舍有共用廚房。"}]', NULL, NULL, 3, 705),
(706, 'dose', '/doʊs/', 'noun', '{"zh-TW":["劑量"],"en":["a quantity of medicine taken at one time"]}', '{"root":{"text":"dose","meaning":"giving (給予)"},"logic":"源自希臘語 dosis（給予的量）。"}', 'recommended dose / daily dose / overdose', '[{"en":"Take one dose every four hours.","zh-TW":"每四小時服用一劑。"},{"en":"The doctor increased the dose of medication.","zh-TW":"醫生增加了藥物劑量。"}]', '{"noun":"dosage","verb":"dose"}', NULL, 1, 706),
(707, 'doubt', '/daʊt/', 'noun', '{"zh-TW":["懷疑；疑慮"],"en":["a feeling of uncertainty"]}', NULL, 'no doubt / beyond doubt', '[{"en":"There is no doubt about his ability.","zh-TW":"他的能力毫無疑問。"},{"en":"I doubt that will work.","zh-TW":"我懷疑那行不通。"}]', '{"noun":"doubt","verb":"doubt","adjective":"doubtful","adverb":"doubtfully"}', NULL, 2, 707),
(708, 'download', '/ˈdaʊnloʊd/', 'verb', '{"zh-TW":["下載"],"en":["to copy data from the internet to a computer"]}', NULL, 'download a file / free download', '[{"en":"Download the app for free.","zh-TW":"免費下載這個應用程式。"},{"en":"The download is almost complete.","zh-TW":"下載快要完成了。"}]', '{"noun":"download"}', NULL, 3, 708),
(709, 'downturn', '/ˈdaʊntɜːrn/', 'noun', '{"zh-TW":["低迷；下滑"],"en":["a decline in economic or business activity"]}', NULL, 'economic downturn / market downturn', '[{"en":"The economic downturn affected all sectors.","zh-TW":"經濟低迷影響了所有行業。"},{"en":"We survived the downturn by cutting costs.","zh-TW":"我們靠削減成本度過了低迷期。"}]', '{"noun":"downturn"}', NULL, 3, 709),
(710, 'draft', '/dræft/', 'noun / verb', '{"zh-TW":["草稿；起草","草稿；草案"],"en":["a preliminary version; to write a first version","a preliminary version of a document"]}', '{"root":{"text":"draft","meaning":"draw (拉/畫)"},"logic":"源自 draw 的變體，指拉出的初步版本。"}', 'first/final draft; first draft / rough draft / draft proposal', '[{"en":"Please review the first draft of the proposal.","zh-TW":"請審閱提案的初稿。"},{"en":"He drafted the contract in one day.","zh-TW":"他一天內起草了合約。"},{"en":"I finished the first draft of my essay.","zh-TW":"我完成了論文的初稿。"},{"en":"The committee reviewed the draft proposal.","zh-TW":"委員會審查了提案草案。"}]', '{"noun":"draft","verb":"draft"}', NULL, 2, 710),
(711, 'drain', '/dreɪn/', 'verb / noun', '{"zh-TW":["排水；耗盡"],"en":["to remove liquid; to use up resources","to remove liquid","to use up resources gradually"]}', '{"root":{"text":"drain","meaning":"dry (乾)"},"logic":"源自古英語 dreahnian（變乾），使水排去。"}', 'drain resources/energy; drain resources / brain drain / drain the water', '[{"en":"The project drained our budget.","zh-TW":"這個項目耗盡了我們的預算。"},{"en":"Brain drain is a serious issue for developing countries.","zh-TW":"人才外流對開發中國家是嚴重問題。"},{"en":"Please drain the water from the pool.","zh-TW":"請把游泳池的水排掉。"},{"en":"The long commute drains my energy.","zh-TW":"長途通勤耗盡我的精力。"}]', '{"noun":"drain/drainage","verb":"drain","noun2":"drainage"}', NULL, 2, 711),
(712, 'drama', '/ˈdrɑːmə/', 'noun', '{"zh-TW":["戲劇；戲劇性事件"],"en":["a play or performance for theater or TV"]}', NULL, 'drama series / drama queen', '[{"en":"She studied drama at university.","zh-TW":"她在大學學戲劇。"},{"en":"There''s always so much drama at work.","zh-TW":"工作中總是有那麼多戲劇性的事。"}]', '{"adjective":"dramatic","adverb":"dramatically"}', NULL, 2, 712),
(713, 'dramatic', '/drəˈmætɪk/', 'adjective', '{"zh-TW":["戲劇性的；顯著的","戲劇性的；巨大的"],"en":["sudden and striking; relating to drama","sudden and striking","relating to drama"]}', '{"root":{"text":"drama","meaning":"action/play (行動/戲)"},"suffix":{"text":"-tic","meaning":"relating to (相關的)"},"logic":"與戲劇性行動相關的。"}', 'dramatic increase/change; dramatic change / dramatic increase / dramatic effect', '[{"en":"There was a dramatic increase in profits.","zh-TW":"利潤有了顯著的增長。"},{"en":"The market saw dramatic changes.","zh-TW":"市場出現了劇烈的變化。"},{"en":"There has been a dramatic increase in sales.","zh-TW":"銷售額有了大幅增加。"},{"en":"The sunset was dramatic and beautiful.","zh-TW":"日落壯觀而美麗。"}]', '{"noun":"drama","adjective":"dramatic","adverb":"dramatically"}', NULL, 3, 713),
(714, 'dream', '/driːm/', 'noun', '{"zh-TW":["夢想；夢"],"en":["a hope or ambition","images during sleep"]}', NULL, 'dream job / dream come true', '[{"en":"This is my dream job.","zh-TW":"這是我的夢想工作。"},{"en":"Starting my own business was a dream come true.","zh-TW":"創業是我夢想成真。"}]', '{"noun":"dream","verb":"dream","adjective":"dreamy","noun2":"dreamer"}', NULL, 2, 714),
(715, 'drink', '/drɪŋk/', 'verb', '{"zh-TW":["喝；飲料"],"en":["to take liquid into the mouth","a liquid for drinking"]}', NULL, 'soft drink / drink water', '[{"en":"Would you like something to drink?","zh-TW":"你想喝點什麼嗎？"},{"en":"Soft drinks are available in the lounge.","zh-TW":"休息室有提供軟性飲料。"}]', '{"verb":"drink","noun":"drink","noun2":"drinker"}', NULL, 2, 715),
(716, 'drive', '/draɪv/', 'verb', '{"zh-TW":["開車；驅動"],"en":["to operate a vehicle","to cause something to happen"]}', NULL, 'drive growth / drive to work', '[{"en":"Innovation drives our growth.","zh-TW":"創新驅動我們的成長。"},{"en":"She drives to work every day.","zh-TW":"她每天開車上班。"}]', '{"verb":"drive","noun":"driver","noun2":"drive"}', NULL, 2, 716),
(717, 'drop', '/drɑːp/', 'verb / noun', '{"zh-TW":["下降；放棄"],"en":["to fall or decrease; to stop doing"]}', NULL, 'drop in price/sales', '[{"en":"Sales dropped by 5% last month.","zh-TW":"上個月銷售額下降了5%。"},{"en":"They decided to drop the project.","zh-TW":"他們決定放棄這個項目。"}]', '{"noun":"drop","verb":"drop"}', NULL, 1, 717),
(718, 'drought', '/draʊt/', 'noun', '{"zh-TW":["乾旱"],"en":["a prolonged period of abnormally low rainfall"]}', '{"root":{"text":"drought","meaning":"dryness (乾燥)"},"logic":"源自古英語 drugaþ（乾燥），指長期缺水。"}', 'severe drought / drought-resistant', '[{"en":"The drought destroyed most of the crops.","zh-TW":"乾旱摧毀了大部分的農作物。"},{"en":"The region is experiencing its worst drought in decades.","zh-TW":"該地區正經歷數十年來最嚴重的乾旱。"}]', NULL, NULL, 3, 718),
(719, 'dry', '/draɪ/', 'adjective', '{"zh-TW":["乾的；乾燥的"],"en":["not wet; without water"]}', NULL, 'dry season / dry cleaning', '[{"en":"The dry season affects our water supply.","zh-TW":"旱季影響我們的供水。"},{"en":"This suit needs dry cleaning.","zh-TW":"這套西裝需要乾洗。"}]', '{"adjective":"dry","verb":"dry","noun":"dryer","noun2":"drought"}', NULL, 1, 719),
(720, 'due', '/djuː/', 'adjective', '{"zh-TW":["到期的；應付的"],"en":["expected at a certain time; owed"]}', NULL, 'due date/due to', '[{"en":"The payment is due on the 15th.","zh-TW":"付款到期日是15號。"},{"en":"The delay was due to bad weather.","zh-TW":"延誤是由於惡劣天氣。"}]', '{"adjective":"due"}', NULL, 1, 720),
(721, 'duplicate', '/ˈdjuːplɪkeɪt/', 'verb / noun', '{"zh-TW":["複製；副本"],"en":["to make an exact copy"]}', NULL, 'avoid duplication', '[{"en":"Please duplicate this report for all managers.","zh-TW":"請為所有經理複製這份報告。"},{"en":"We need to eliminate duplicate records.","zh-TW":"我們需要消除重複的記錄。"}]', '{"noun":"duplicate/duplication","verb":"duplicate"}', NULL, 3, 721),
(722, 'duration', '/djuˈreɪʃən/', 'noun', '{"zh-TW":["持續時間"],"en":["the time during which something continues","the length of time something continues"]}', '{"root":{"text":"dur","meaning":"last/hard (持久)"},"suffix":{"text":"-ation","meaning":"state (狀態)"},"logic":"持續的狀態，即「持續時間」。"}', 'for the duration of; for the duration of / short duration', '[{"en":"The contract is valid for the duration of the project.","zh-TW":"合約在項目期間有效。"},{"en":"What is the duration of the training?","zh-TW":"培訓的持續時間是多長？"},{"en":"The flight duration is approximately 12 hours.","zh-TW":"飛行時間約12小時。"},{"en":"For the duration of the event, parking is free.","zh-TW":"活動期間停車免費。"}]', '{"noun":"duration","adjective":"durable","verb":"endure"}', NULL, 3, 722),
(723, 'duty', '/ˈdjuːti/', 'noun', '{"zh-TW":["職責；關稅"],"en":["a moral or legal obligation; a tax on imports"]}', NULL, 'on/off duty', '[{"en":"It is your duty to report any safety issues.","zh-TW":"報告任何安全問題是你的職責。"},{"en":"Import duties have been raised.","zh-TW":"進口關稅已提高。"}]', '{"noun":"duty","adjective":"dutiful"}', NULL, 1, 723),
(724, 'dwell', '/dwel/', 'verb', '{"zh-TW":["居住；老是想著"],"en":["to live in a place","to think about something at length"]}', '{"root":{"text":"dwell","meaning":"lead astray/delay (耽擱)"},"logic":"源自古英語 dwellan（耽擱），引申為停留、居住。"}', 'dwell on / dwell in / dwelling place', '[{"en":"Don''t dwell on past mistakes.","zh-TW":"不要老想著過去的錯誤。"},{"en":"Many species dwell in the rainforest.","zh-TW":"許多物種棲息在雨林中。"}]', '{"noun":"dwelling","noun2":"dweller"}', NULL, 2, 724),
(725, 'dynamic', '/daɪˈnæmɪk/', 'adjective', '{"zh-TW":["動態的；有活力的","動態的；充滿活力的"],"en":["characterized by constant change and activity","characterized by constant change or activity"]}', '{"root":{"text":"dynam","meaning":"power (力量)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與力量和活動相關的，即「動態的」。"}', 'dynamic environment/market; dynamic environment / dynamic personality', '[{"en":"The tech industry is highly dynamic.","zh-TW":"科技產業高度動態。"},{"en":"She is a dynamic leader.","zh-TW":"她是一位有活力的領導者。"},{"en":"The business operates in a dynamic market.","zh-TW":"這家企業在活躍的市場中運營。"},{"en":"She has a very dynamic personality.","zh-TW":"她有非常有活力的個性。"}]', '{"noun":"dynamics","adjective":"dynamic","adverb":"dynamically"}', NULL, 3, 725),
(726, 'eager', '/ˈiːɡər/', 'adjective', '{"zh-TW":["渴望的；熱切的"],"en":["strongly wanting to do or have something"]}', '{"root":{"text":"eager","meaning":"sharp/keen (尖銳/敏銳)"},"logic":"源自拉丁語 acer（尖銳的），指熱切渴望的。"}', 'eager to learn / eager for', '[{"en":"Students were eager to start the project.","zh-TW":"學生們渴望開始這個專案。"},{"en":"She is eager for new experiences.","zh-TW":"她熱切期望新體驗。"}]', '{"noun":"eagerness","adverb":"eagerly"}', NULL, 2, 726),
(727, 'early', '/ˈɜːrli/', 'adjective', '{"zh-TW":["早的；提前的"],"en":["before the expected time","near the beginning of a period"]}', NULL, 'early morning / early stage', '[{"en":"We are still in the early stages.","zh-TW":"我們仍處於早期階段。"},{"en":"She arrived early for the interview.","zh-TW":"她面試提前到達。"}]', '{"adjective":"early","adverb":"early"}', NULL, 2, 727),
(728, 'earn', '/ɜːrn/', 'verb', '{"zh-TW":["賺取；贏得"],"en":["to receive money for work; to gain through effort"]}', NULL, 'earn a living/reputation', '[{"en":"She earns a good salary as a consultant.","zh-TW":"她作為顧問賺取了不錯的薪水。"},{"en":"He earned the respect of his colleagues.","zh-TW":"他贏得了同事的尊重。"}]', '{"noun":"earnings","verb":"earn"}', NULL, 1, 728),
(729, 'earth', '/ɜːrθ/', 'noun', '{"zh-TW":["地球；土地"],"en":["the planet we live on","soil"]}', NULL, 'on earth / earth-friendly', '[{"en":"We promote earth-friendly products.","zh-TW":"我們推廣環保產品。"},{"en":"What on earth happened?","zh-TW":"到底發生了什麼事？"}]', '{"noun":"earth","adjective":"earthy","adjective2":"earthly"}', NULL, 2, 729),
(730, 'earthquake', '/ˈɜːrθkweɪk/', 'noun', '{"zh-TW":["地震"],"en":["a sudden violent shaking of the ground"]}', '{"root":{"text":"earth","meaning":"ground (地面)"},"suffix":{"text":"quake","meaning":"shake (搖晃)"},"logic":"地面搖晃，即「地震」。"}', 'earthquake damage / earthquake-proof', '[{"en":"The earthquake measured 7.2 on the Richter scale.","zh-TW":"地震規模達到芮氏7.2級。"},{"en":"Buildings in Japan are designed to withstand earthquakes.","zh-TW":"日本的建築設計能承受地震。"}]', NULL, NULL, 4, 730),
(731, 'ease', '/iːz/', 'noun / verb', '{"zh-TW":["輕鬆；緩解"],"en":["absence of difficulty; to make less severe"]}', NULL, 'with ease / ease the pressure', '[{"en":"She completed the task with ease.","zh-TW":"她輕鬆地完成了任務。"},{"en":"The new policy will ease the financial burden.","zh-TW":"新政策將緩解經濟負擔。"}]', '{"noun":"ease","verb":"ease","adjective":"easy"}', NULL, 1, 731),
(732, 'easy', '/ˈiːzi/', 'adjective', '{"zh-TW":["容易的；輕鬆的"],"en":["not difficult","comfortable"]}', NULL, 'easy to use / take it easy', '[{"en":"The software is easy to use.","zh-TW":"這個軟體很容易使用。"},{"en":"Take it easy this weekend.","zh-TW":"這週末輕鬆一下吧。"}]', '{"adjective":"easy","adverb":"easily","noun":"ease","verb":"ease"}', NULL, 1, 732),
(733, 'eat', '/iːt/', 'verb', '{"zh-TW":["吃"],"en":["to put food in the mouth, chew, and swallow"]}', NULL, 'eat out / eat healthy', '[{"en":"We often eat out with clients.","zh-TW":"我們常和客戶外出用餐。"},{"en":"Try to eat healthy during work trips.","zh-TW":"出差期間盡量吃得健康。"}]', '{"verb":"eat","noun":"eater","adjective":"edible"}', NULL, 1, 733),
(734, 'eclipse', '/ɪˈklɪps/', 'noun', '{"zh-TW":["日食；月食"],"en":["the blocking of light from the sun or moon"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"clips","meaning":"fail/leave (離去)"},"logic":"光芒離去，即「食」（日食/月食）。"}', 'solar eclipse / lunar eclipse / total eclipse', '[{"en":"A total solar eclipse will occur next month.","zh-TW":"下個月將發生日全食。"},{"en":"The lunar eclipse was visible across Asia.","zh-TW":"月食在亞洲各地都能看到。"}]', '{"verb":"eclipse"}', NULL, 3, 734),
(735, 'economy', '/ɪˈkɑːnəmi/', 'noun', '{"zh-TW":["經濟；節約"],"en":["the system of trade and industry; careful use of resources"]}', NULL, 'global/national economy', '[{"en":"The economy is expected to grow by 3%.","zh-TW":"預計經濟將增長3%。"},{"en":"We need to practice economy in spending.","zh-TW":"我們需要節約開支。"}]', '{"noun":"economy/economics/economist","adjective":"economic/economical"}', NULL, 3, 735),
(736, 'edit', '/ˈedɪt/', 'verb', '{"zh-TW":["編輯；修改"],"en":["to prepare written material for publication"]}', NULL, 'edit a document/video', '[{"en":"Please edit the report before submission.","zh-TW":"請在提交前編輯報告。"},{"en":"The article was heavily edited.","zh-TW":"這篇文章經過大量修改。"}]', '{"noun":"edition/editor","verb":"edit","adjective":"editorial"}', NULL, 1, 736),
(737, 'educate', '/ˈedʒukeɪt/', 'verb', '{"zh-TW":["教育；培養"],"en":["to give intellectual or moral instruction"]}', NULL, 'educate the public', '[{"en":"The program aims to educate consumers about nutrition.","zh-TW":"該計畫旨在教育消費者有關營養的知識。"},{"en":"She was educated at Oxford University.","zh-TW":"她在牛津大學接受教育。"}]', '{"noun":"education/educator","verb":"educate","adjective":"educational/educated"}', NULL, 3, 737),
(738, 'effect', '/ɪˈfekt/', 'noun', '{"zh-TW":["效果；影響"],"en":["a change produced by an action or cause"]}', NULL, 'have an effect on / take effect', '[{"en":"The new law will take effect next month.","zh-TW":"新法律將於下個月生效。"},{"en":"The policy had a positive effect on sales.","zh-TW":"該政策對銷售產生了積極影響。"}]', '{"noun":"effect/effectiveness","adjective":"effective","adverb":"effectively"}', NULL, 2, 738),
(739, 'efficient', '/ɪˈfɪʃənt/', 'adjective', '{"zh-TW":["高效的","有效率的"],"en":["achieving maximum output with minimum waste","achieving maximum productivity with minimum waste"]}', '{"prefix":{"text":"ef-","meaning":"out (出)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做出成果的，即「有效率的」。"}', 'cost-efficient / energy-efficient; energy-efficient / cost-efficient / highly efficient', '[{"en":"The new system is more efficient.","zh-TW":"新系統更加高效。"},{"en":"We need to find a more efficient solution.","zh-TW":"我們需要找到更高效的解決方案。"},{"en":"This engine is more fuel-efficient.","zh-TW":"這個引擎更省油。"},{"en":"We need a more efficient way to process orders.","zh-TW":"我們需要更有效率的方式處理訂單。"}]', '{"noun":"efficiency","adjective":"efficient","adverb":"efficiently"}', NULL, 3, 739),
(740, 'effort', '/ˈefərt/', 'noun', '{"zh-TW":["努力；成果"],"en":["a determined attempt; physical or mental energy used"]}', NULL, 'make an effort / considerable effort', '[{"en":"It took a lot of effort to complete the project.","zh-TW":"完成這個項目花了很多努力。"},{"en":"Please make an effort to arrive on time.","zh-TW":"請努力準時到達。"}]', '{"noun":"effort","adjective":"effortless"}', NULL, 2, 740),
(741, 'elaborate', '/ɪˈlæbərət/', 'adjective / verb', '{"zh-TW":["精心的；詳述"],"en":["detailed and complicated; to explain in more detail"]}', NULL, 'elaborate on/plan', '[{"en":"Could you elaborate on your proposal?","zh-TW":"你能詳細說明你的提案嗎？"},{"en":"They developed an elaborate marketing strategy.","zh-TW":"他們制定了精心的行銷策略。"}]', '{"noun":"elaboration","verb":"elaborate","adjective":"elaborate"}', NULL, 3, 741),
(742, 'elect', '/ɪˈlekt/', 'verb', '{"zh-TW":["選舉；選擇"],"en":["to choose by voting"]}', NULL, 'elect a president/chairperson', '[{"en":"She was elected as the new chairperson.","zh-TW":"她被選為新主席。"},{"en":"Members elect the board annually.","zh-TW":"成員每年選舉董事會。"}]', '{"noun":"election","verb":"elect","adjective":"elected/electoral"}', NULL, 2, 742),
(743, 'elective', '/ɪˈlɛktɪv/', 'noun', '{"zh-TW":["選修課"],"en":["a course that students can choose to take"]}', NULL, 'elective course / take an elective', '[{"en":"Art is an elective at our school.","zh-TW":"藝術在我們學校是選修課。"},{"en":"Students must take two electives.","zh-TW":"學生必須選修兩門選修課。"}]', NULL, NULL, 3, 743),
(744, 'element', '/ˈelɪmənt/', 'noun', '{"zh-TW":["要素；元素"],"en":["a component or part of something"]}', NULL, 'key/essential element', '[{"en":"Trust is a key element of teamwork.","zh-TW":"信任是團隊合作的關鍵要素。"},{"en":"The plan has several important elements.","zh-TW":"該計畫有幾個重要的要素。"}]', '{"noun":"element","adjective":"elementary"}', NULL, 3, 744),
(745, 'elevate', '/ˈelɪveɪt/', 'verb', '{"zh-TW":["提升；提高"],"en":["to raise to a higher position or level"]}', NULL, 'elevate standards/status', '[{"en":"The promotion elevated her to senior manager.","zh-TW":"升遷使她晉升為高級經理。"},{"en":"We aim to elevate customer experience.","zh-TW":"我們的目標是提升客戶體驗。"}]', '{"noun":"elevation/elevator","verb":"elevate","adjective":"elevated"}', NULL, 3, 745),
(746, 'eligible', '/ˈelɪdʒəbəl/', 'adjective', '{"zh-TW":["合格的；有資格的"],"en":["meeting the conditions to do or receive something"]}', NULL, 'eligible for/to', '[{"en":"All full-time employees are eligible for benefits.","zh-TW":"所有全職員工都有資格享受福利。"},{"en":"You must be 18 to be eligible to vote.","zh-TW":"你必須年滿18歲才有投票資格。"}]', '{"noun":"eligibility","adjective":"eligible"}', NULL, 3, 746),
(747, 'eliminate', '/ɪˈlɪmɪneɪt/', 'verb', '{"zh-TW":["消除；淘汰"],"en":["to completely remove or get rid of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"limin","meaning":"threshold (門檻)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使超出門檻之外，即「淘汰」。"}', 'eliminate waste/errors; eliminate waste / eliminate the possibility', '[{"en":"We need to eliminate unnecessary costs.","zh-TW":"我們需要消除不必要的成本。"},{"en":"The company eliminated 200 positions.","zh-TW":"公司裁撤了200個職位。"},{"en":"The team was eliminated in the first round.","zh-TW":"該隊在第一輪就被淘汰了。"}]', '{"noun":"elimination","verb":"eliminate"}', NULL, 3, 747),
(748, 'embarrassed', '/ɪmˈbærəst/', 'adjective', '{"zh-TW":["尷尬的；難為情的"],"en":["feeling ashamed or shy"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"barrass","meaning":"bar/obstruct (阻礙)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"感覺被阻礙住的，即「尷尬的」。"}', 'feel embarrassed / embarrassed about', '[{"en":"He was embarrassed by his mistake.","zh-TW":"他因犯錯而感到尷尬。"},{"en":"She felt embarrassed in front of everyone.","zh-TW":"她在眾人面前感到難為情。"}]', '{"noun":"embarrassment","adjective":"embarrassing","verb":"embarrass"}', NULL, 4, 748),
(749, 'embrace', '/ɪmˈbreɪs/', 'verb', '{"zh-TW":["擁抱；接受"],"en":["to accept willingly; to hold closely"]}', NULL, 'embrace change/technology', '[{"en":"Companies must embrace new technology.","zh-TW":"企業必須擁抱新技術。"},{"en":"She embraced the opportunity eagerly.","zh-TW":"她熱切地接受了這個機會。"}]', '{"noun":"embrace","verb":"embrace"}', NULL, 3, 749);
