(750, 'emerge', '/ɪˈmɜːrdʒ/', 'verb', '{"zh-TW":["出現；浮現"],"en":["to come into view; to become known","to come into view or existence"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"merge","meaning":"dip/plunge (浸入)"},"logic":"從水中浮出，即「出現」。"}', 'emerge as/from; emerge from / emerging market / emerge as', '[{"en":"New competitors are emerging in the market.","zh-TW":"市場上出現了新的競爭者。"},{"en":"The company emerged as a market leader.","zh-TW":"該公司成為市場領導者。"},{"en":"New evidence emerged during the investigation.","zh-TW":"調查期間浮現了新證據。"},{"en":"She emerged as the leading candidate.","zh-TW":"她脫穎而出成為領先的候選人。"}]', '{"noun":"emergence","verb":"emerge","adjective":"emerging/emergent"}', NULL, 2, 750),
(751, 'emergency', '/ɪˈmɜːrdʒənsi/', 'noun', '{"zh-TW":["緊急情況"],"en":["a serious unexpected situation requiring immediate action"]}', NULL, 'in case of emergency', '[{"en":"Call 911 in case of an emergency.","zh-TW":"緊急情況下請撥打911。"},{"en":"An emergency meeting was called.","zh-TW":"召開了緊急會議。"}]', '{"noun":"emergency","adjective":"emergency"}', NULL, 3, 751),
(752, 'emission', '/ɪˈmɪʃən/', 'noun', '{"zh-TW":["排放；排放物"],"en":["the production and discharge of something, especially gas"]}', NULL, 'carbon/greenhouse emissions', '[{"en":"The factory must reduce its carbon emissions.","zh-TW":"工廠必須減少碳排放。"},{"en":"Emission standards are becoming stricter.","zh-TW":"排放標準越來越嚴格。"}]', '{"noun":"emission","verb":"emit"}', NULL, 3, 752),
(753, 'emotion', '/ɪˈmoʊʃn/', 'noun', '{"zh-TW":["情緒；情感"],"en":["a strong feeling such as joy, anger, or sadness"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"從內心移動出來的感覺，即「情緒」。"}', 'strong emotion / show emotion / mixed emotions', '[{"en":"She couldn''t hide her emotions.","zh-TW":"她無法隱藏自己的情緒。"},{"en":"The movie evoked strong emotions.","zh-TW":"這部電影激發了強烈的情感。"}]', '{"adjective":"emotional","adverb":"emotionally"}', NULL, 3, 753),
(754, 'empathy', '/ˈempəθi/', 'noun', '{"zh-TW":["同理心"],"en":["the ability to understand and share another''s feelings"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"進入他人感受中，即「同理心」。"}', 'show empathy / lack of empathy', '[{"en":"A good therapist shows empathy toward patients.","zh-TW":"好的治療師對病人展現同理心。"},{"en":"Empathy is important in building relationships.","zh-TW":"同理心在建立關係中很重要。"}]', '{"adjective":"empathetic","verb":"empathize"}', NULL, 3, 754),
(755, 'emphasis', '/ˈemfəsɪs/', 'noun', '{"zh-TW":["強調；重點"],"en":["special importance given to something"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"phas","meaning":"show (展現)"},"suffix":{"text":"-is","meaning":"state (狀態)"},"logic":"在其中展現出重要性，即「強調」。"}', 'place/put emphasis on; place emphasis on / with emphasis / special emphasis', '[{"en":"The company places great emphasis on quality.","zh-TW":"公司非常重視品質。"},{"en":"There is growing emphasis on sustainability.","zh-TW":"對永續發展的重視日益增長。"},{"en":"The school places emphasis on creative thinking.","zh-TW":"學校強調創意思考。"},{"en":"She spoke with great emphasis.","zh-TW":"她說話時特別加重語氣。"}]', '{"noun":"emphasis","verb":"emphasize","adjective":"emphatic"}', NULL, 3, 755),
(756, 'employ', '/ɪmˈplɔɪ/', 'verb', '{"zh-TW":["僱用；使用","雇用；運用"],"en":["to give work to someone; to use","to give work to someone","to make use of"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"ploy","meaning":"fold/use (使用)"},"logic":"把人用進來，即「雇用」。"}', 'employ staff/methods; employ staff / employ a strategy / currently employed', '[{"en":"The company employs over 5,000 people.","zh-TW":"該公司僱用了5000多人。"},{"en":"We employ various strategies to boost sales.","zh-TW":"我們使用各種策略來促進銷售。"},{"en":"The company employs over 500 people.","zh-TW":"公司雇用超過500人。"},{"en":"She employed a new strategy to solve the problem.","zh-TW":"她運用了新策略來解決問題。"}]', '{"noun":"employment/employee/employer","verb":"employ","noun2":"employee","noun3":"employer"}', NULL, 2, 756),
(757, 'empower', '/ɪmˈpaʊər/', 'verb', '{"zh-TW":["賦予權力；使能夠"],"en":["to give someone authority or confidence"]}', NULL, 'empower employees/women', '[{"en":"The training empowers employees to make decisions.","zh-TW":"培訓賦予員工做決定的能力。"},{"en":"Technology empowers small businesses to compete.","zh-TW":"技術使小企業能夠參與競爭。"}]', '{"noun":"empowerment","verb":"empower"}', NULL, 3, 757),
(758, 'empty', '/ˈɛmpti/', 'adjective', '{"zh-TW":["空的"],"en":["containing nothing; not filled"]}', NULL, 'empty space / empty promise', '[{"en":"The meeting room is empty now.","zh-TW":"會議室現在是空的。"},{"en":"Don''t make empty promises.","zh-TW":"別做空洞的承諾。"}]', '{"adjective":"empty","verb":"empty","noun":"emptiness"}', NULL, 2, 758),
(759, 'enable', '/ɪˈneɪbəl/', 'verb', '{"zh-TW":["使能夠；啟用"],"en":["to make possible or allow","to make possible or provide the means for"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"able","meaning":"able (能夠)"},"logic":"使其能夠，即「使能夠」。"}', 'enable + 人 + to; enable access / enable growth', '[{"en":"The software enables users to track expenses.","zh-TW":"該軟體使用戶能夠追蹤支出。"},{"en":"This funding will enable further research.","zh-TW":"這筆資金將使進一步研究成為可能。"},{"en":"Technology enables people to work from home.","zh-TW":"科技使人們能在家工作。"},{"en":"The grant enabled her to continue her research.","zh-TW":"這筆補助使她能繼續研究。"}]', '{"verb":"enable","adjective":"enabling"}', NULL, 2, 759),
(760, 'enact', '/ɪˈnækt/', 'verb', '{"zh-TW":["制定；頒布"],"en":["to make a bill into law"]}', NULL, 'enact legislation/a policy', '[{"en":"The government enacted new environmental regulations.","zh-TW":"政府制定了新的環境法規。"},{"en":"The law was enacted in 2020.","zh-TW":"該法律於2020年頒布。"}]', '{"noun":"enactment","verb":"enact"}', NULL, 2, 760),
(761, 'encounter', '/ɪnˈkaʊntər/', 'verb / noun', '{"zh-TW":["遭遇；碰到","遭遇；偶遇"],"en":["to unexpectedly meet or face","to unexpectedly meet or face something"]}', '{"prefix":{"text":"en-","meaning":"in (在)"},"root":{"text":"counter","meaning":"against (對面)"},"logic":"在對面碰上，即「遭遇」。"}', 'encounter difficulties/problems; encounter problems / encounter difficulties', '[{"en":"We encountered several problems during installation.","zh-TW":"我們在安裝過程中遇到了幾個問題。"},{"en":"It was her first encounter with the CEO.","zh-TW":"這是她第一次與執行長碰面。"},{"en":"We encountered several problems along the way.","zh-TW":"我們一路上遇到了幾個問題。"},{"en":"I encountered an old friend at the airport.","zh-TW":"我在機場偶遇一位老朋友。"}]', '{"noun":"encounter","verb":"encounter"}', NULL, 3, 761),
(762, 'encourage', '/ɪnˈkɜːrɪdʒ/', 'verb', '{"zh-TW":["鼓勵；促進"],"en":["to give support or confidence"]}', NULL, 'encourage + 人 + to', '[{"en":"The manager encouraged her team to innovate.","zh-TW":"經理鼓勵她的團隊創新。"},{"en":"Low interest rates encourage borrowing.","zh-TW":"低利率鼓勵借貸。"}]', '{"noun":"encouragement","verb":"encourage","adjective":"encouraging"}', NULL, 3, 762),
(763, 'encryption', '/ɪnˈkrɪpʃən/', 'noun', '{"zh-TW":["加密"],"en":["the process of converting data into a secret code"]}', NULL, 'data encryption / end-to-end encryption', '[{"en":"The message uses end-to-end encryption.","zh-TW":"訊息使用端對端加密。"},{"en":"Encryption protects your data.","zh-TW":"加密保護你的資料。"}]', '{"verb":"encrypt","adjective":"encrypted"}', NULL, 4, 763),
(764, 'end', '/ɛnd/', 'noun', '{"zh-TW":["結束；末端"],"en":["the final part","to finish"]}', NULL, 'at the end / end up', '[{"en":"At the end of the month, we review performance.","zh-TW":"月底我們會檢討績效。"},{"en":"The contract ends next year.","zh-TW":"合約明年到期。"}]', '{"noun":"end","verb":"end","adjective":"endless","noun2":"ending"}', NULL, 1, 764),
(765, 'endorse', '/ɪnˈdɔːrs/', 'verb', '{"zh-TW":["背書；認可"],"en":["to publicly approve or support"]}', NULL, 'endorse a product/candidate', '[{"en":"Several celebrities endorsed the brand.","zh-TW":"多位名人為該品牌背書。"},{"en":"The board endorsed the new strategy.","zh-TW":"董事會認可了新策略。"}]', '{"noun":"endorsement","verb":"endorse"}', NULL, 3, 765),
(766, 'enemy', '/ˈɛnəmi/', 'noun', '{"zh-TW":["敵人；敵方"],"en":["a person who is hostile to another"]}', NULL, 'worst enemy / make enemies', '[{"en":"Procrastination is your worst enemy.","zh-TW":"拖延是你最大的敵人。"},{"en":"Don''t make enemies in the industry.","zh-TW":"別在業界樹敵。"}]', '{"noun":"enemy","noun2":"enmity"}', NULL, 2, 766),
(767, 'enforce', '/ɪnˈfɔːrs/', 'verb', '{"zh-TW":["執行；強制","執行；強制實施"],"en":["to compel compliance with a law or rule","to make sure a law or rule is obeyed"]}', NULL, 'enforce regulations/rules; enforce the law / strictly enforced', '[{"en":"The police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The contract will be strictly enforced.","zh-TW":"合約將被嚴格執行。"},{"en":"Police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The rules are strictly enforced.","zh-TW":"規則被嚴格執行。"}]', '{"noun":"enforcement","verb":"enforce","adjective":"enforceable"}', NULL, 3, 767),
(768, 'engage', '/ɪnˈɡeɪdʒ/', 'verb', '{"zh-TW":["參與；僱用","參與；吸引"],"en":["to participate; to attract attention","to participate or become involved","to attract someone''s attention"]}', '{"prefix":{"text":"en-","meaning":"in (進入)"},"root":{"text":"gage","meaning":"pledge (承諾)"},"logic":"進入承諾參與，即「參與」。"}', 'engage in/with; engage in / engage with / engage employees', '[{"en":"The company engages in sustainable practices.","zh-TW":"公司參與永續實踐。"},{"en":"We need to engage more customers online.","zh-TW":"我們需要在線上吸引更多客戶。"},{"en":"Students are encouraged to engage in discussions.","zh-TW":"鼓勵學生參與討論。"},{"en":"The presentation engaged the entire audience.","zh-TW":"報告吸引了全場觀眾。"}]', '{"noun":"engagement","verb":"engage","adjective":"engaging/engaged"}', NULL, 2, 768),
(769, 'engine', '/ˈɛndʒɪn/', 'noun', '{"zh-TW":["引擎；發動機"],"en":["a machine that converts energy into motion"]}', NULL, 'search engine / engine of growth', '[{"en":"Use a search engine to find information.","zh-TW":"使用搜尋引擎查找資訊。"},{"en":"Technology is the engine of growth.","zh-TW":"科技是成長的引擎。"}]', '{"noun":"engine","noun2":"engineer","noun3":"engineering"}', NULL, 2, 769),
(770, 'enhance', '/ɪnˈhæns/', 'verb', '{"zh-TW":["增強；提高","增強；提升"],"en":["to improve the quality or value of","to improve the quality or value of something"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"hance","meaning":"high (高)"},"logic":"使其提高，即「增強」。"}', 'enhance performance/productivity; enhance performance / enhance quality / enhance the experience', '[{"en":"The update will enhance system performance.","zh-TW":"更新將增強系統性能。"},{"en":"Training enhances employee productivity.","zh-TW":"培訓提高員工生產力。"},{"en":"This software enhances image quality.","zh-TW":"這個軟體增強了影像品質。"},{"en":"The new features enhance the user experience.","zh-TW":"新功能提升了使用者體驗。"}]', '{"noun":"enhancement","verb":"enhance"}', NULL, 3, 770),
(771, 'enjoy', '/ɪnˈdʒɔɪ/', 'verb', '{"zh-TW":["享受；喜歡"],"en":["to get pleasure from something"]}', NULL, 'enjoy doing / enjoy the benefits', '[{"en":"I enjoy working with this team.","zh-TW":"我喜歡和這個團隊一起工作。"},{"en":"Members enjoy special benefits.","zh-TW":"會員享有特殊福利。"}]', '{"verb":"enjoy","noun":"enjoyment","adjective":"enjoyable"}', NULL, 2, 771),
(772, 'enormous', '/ɪˈnɔːrməs/', 'adjective', '{"zh-TW":["巨大的"],"en":["very large in size, quantity, or extent","very large in size or quantity"]}', '{"prefix":{"text":"e-","meaning":"out (超出)"},"root":{"text":"norm","meaning":"rule/standard (標準)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"超出正常標準的，即「巨大的」。"}', 'enormous amount/potential; enormous amount / enormous pressure / enormous success', '[{"en":"The project requires an enormous investment.","zh-TW":"該項目需要巨額投資。"},{"en":"There is enormous potential for growth.","zh-TW":"有巨大的增長潛力。"},{"en":"The project requires an enormous amount of work.","zh-TW":"這個專案需要大量的工作。"},{"en":"The concert was an enormous success.","zh-TW":"音樂會獲得了巨大的成功。"}]', '{"adjective":"enormous","adverb":"enormously"}', NULL, 3, 772),
(773, 'enough', '/ɪˈnʌf/', 'adjective', '{"zh-TW":["足夠的"],"en":["as much as is needed"]}', NULL, 'good enough / not enough', '[{"en":"We don''t have enough staff for this project.","zh-TW":"我們沒有足夠的人手做這個專案。"},{"en":"Is this good enough?","zh-TW":"這樣夠好嗎？"}]', '{"adjective":"enough","adverb":"enough"}', NULL, 2, 773),
(774, 'enroll', '/ɪnˈroʊl/', 'verb', '{"zh-TW":["註冊；登記","註冊；入學"],"en":["to officially register for a course or program","to officially join a course or school"]}', NULL, 'enroll in a course/program; enroll in / enrollment period', '[{"en":"Over 500 students enrolled in the program.","zh-TW":"超過500名學生註冊了該計畫。"},{"en":"You can enroll online.","zh-TW":"你可以在線上註冊。"},{"en":"She enrolled in a language course.","zh-TW":"她報名了一門語言課程。"},{"en":"Over 500 students enrolled this year.","zh-TW":"今年有超過500名學生入學。"}]', '{"noun":"enrollment","verb":"enroll"}', NULL, 2, 774),
(775, 'ensure', '/ɪnˈʃʊr/', 'verb', '{"zh-TW":["確保"],"en":["to make certain that something happens"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"使其確定，即「確保」。"}', 'ensure quality/safety; ensure quality / ensure safety / ensure that', '[{"en":"Please ensure all data is backed up.","zh-TW":"請確保所有資料都已備份。"},{"en":"We must ensure customer satisfaction.","zh-TW":"我們必須確保客戶滿意度。"},{"en":"Please ensure all doors are locked.","zh-TW":"請確保所有門都已上鎖。"},{"en":"We must ensure the safety of our employees.","zh-TW":"我們必須確保員工的安全。"}]', '{"verb":"ensure"}', NULL, 2, 775),
(776, 'enter', '/ˈɛntər/', 'verb', '{"zh-TW":["進入；輸入"],"en":["to go into a place","to type data"]}', NULL, 'enter the market / enter data', '[{"en":"They plan to enter the Asian market.","zh-TW":"他們計畫進入亞洲市場。"},{"en":"Please enter your password.","zh-TW":"請輸入你的密碼。"}]', '{"verb":"enter","noun":"entrance","noun2":"entry"}', NULL, 2, 776),
(777, 'enterprise', '/ˈentərpraɪz/', 'noun', '{"zh-TW":["企業；事業"],"en":["a business or company; a bold undertaking"]}', NULL, 'private/state enterprise', '[{"en":"Small enterprises drive economic growth.","zh-TW":"小型企業推動經濟增長。"},{"en":"The new enterprise launched last quarter.","zh-TW":"新企業上季度啟動了。"}]', '{"noun":"enterprise","adjective":"enterprising"}', NULL, 4, 777),
(778, 'entertainment', '/ˌɛntərˈteɪnmənt/', 'noun', '{"zh-TW":["娛樂"],"en":["activities for enjoyment"]}', NULL, 'entertainment industry / live entertainment', '[{"en":"The hotel offers nightly entertainment.","zh-TW":"飯店每晚提供娛樂節目。"},{"en":"The entertainment industry is growing.","zh-TW":"娛樂產業正在成長。"}]', '{"verb":"entertain","noun2":"entertainer","adjective":"entertaining"}', NULL, 5, 778),
(779, 'enthusiastic', '/ɪnˌθjuːziˈæstɪk/', 'adjective', '{"zh-TW":["熱情的；熱心的"],"en":["showing intense enjoyment or interest"]}', '{"prefix":{"text":"en-","meaning":"in (在內)"},"root":{"text":"thusi","meaning":"god (神)"},"suffix":{"text":"-astic","meaning":"relating to (相關的)"},"logic":"如同有神靈附體般的熱情。"}', 'enthusiastic about / enthusiastic response', '[{"en":"She is enthusiastic about her new job.","zh-TW":"她對新工作充滿熱情。"},{"en":"The audience gave an enthusiastic response.","zh-TW":"觀眾給予熱烈回應。"}]', '{"noun":"enthusiasm","adverb":"enthusiastically"}', NULL, 4, 779),
(780, 'entire', '/ɪnˈtaɪər/', 'adjective', '{"zh-TW":["整個的；全部的"],"en":["whole; complete","with no part left out; whole"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"tire","meaning":"touch/diminish (觸及/削減)"},"logic":"未被削減的，即「完整的」。"}', 'the entire team/process; the entire team / the entire day / in its entirety', '[{"en":"The entire team was present at the meeting.","zh-TW":"整個團隊都出席了會議。"},{"en":"She spent the entire day on the report.","zh-TW":"她花了一整天在報告上。"},{"en":"The entire team worked overtime.","zh-TW":"整個團隊加班工作。"},{"en":"She read the entire book in one day.","zh-TW":"她一天內讀完了整本書。"}]', '{"adjective":"entire","adverb":"entirely","noun":"entirety"}', NULL, 2, 780),
(781, 'entitle', '/ɪnˈtaɪtəl/', 'verb', '{"zh-TW":["賦予權利；命名"],"en":["to give someone the right to do something"]}', NULL, 'be entitled to', '[{"en":"Full-time staff are entitled to 20 days of leave.","zh-TW":"全職員工有權享有20天假期。"},{"en":"The book is entitled ''Modern Management''.","zh-TW":"這本書名為《現代管理》。"}]', '{"noun":"entitlement","verb":"entitle","adjective":"entitled"}', NULL, 3, 781),
(782, 'entrepreneur', '/ˌɑːntrəprəˈnɜːr/', 'noun', '{"zh-TW":["企業家；創業者"],"en":["a person who starts and runs a business"]}', NULL, 'successful entrepreneur', '[{"en":"She is a successful entrepreneur in tech.","zh-TW":"她是科技領域的成功企業家。"},{"en":"Entrepreneurs drive innovation.","zh-TW":"企業家推動創新。"}]', '{"noun":"entrepreneur/entrepreneurship","adjective":"entrepreneurial"}', NULL, 4, 782),
(783, 'environment', '/ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["環境"],"en":["the natural world; surrounding conditions"]}', NULL, 'work/business environment', '[{"en":"We must protect the environment.","zh-TW":"我們必須保護環境。"},{"en":"A positive work environment boosts morale.","zh-TW":"積極的工作環境提升士氣。"}]', '{"noun":"environment/environmentalist","adjective":"environmental","adverb":"environmentally"}', NULL, 4, 783),
(784, 'equal', '/ˈiːkwəl/', 'adjective / verb', '{"zh-TW":["相等的；等於"],"en":["the same in quantity, size, or value"]}', NULL, 'equal opportunity/rights', '[{"en":"All employees should receive equal pay for equal work.","zh-TW":"所有員工同工應同酬。"},{"en":"The total equals $5,000.","zh-TW":"總計等於5000美元。"}]', '{"noun":"equality","verb":"equal","adjective":"equal","adverb":"equally"}', NULL, 2, 784),
(785, 'equip', '/ɪˈkwɪp/', 'verb', '{"zh-TW":["裝備；配備"],"en":["to provide with necessary items or skills"]}', NULL, 'well-equipped / equip with', '[{"en":"The office is equipped with modern technology.","zh-TW":"辦公室配備了現代技術。"},{"en":"Training equips employees with new skills.","zh-TW":"培訓為員工配備新技能。"}]', '{"noun":"equipment","verb":"equip","adjective":"equipped"}', NULL, 2, 785),
(786, 'equity', '/ˈɛkwɪti/', 'noun', '{"zh-TW":["股權；權益"],"en":["the value of shares in a company","fairness"]}', NULL, 'private equity / home equity', '[{"en":"They raised capital through private equity.","zh-TW":"他們透過私募股權募集資金。"},{"en":"The company has strong brand equity.","zh-TW":"公司擁有強大的品牌價值。"}]', '{"noun":"equity","adjective":"equitable"}', NULL, 2, 786),
(787, 'equivalent', '/ɪˈkwɪvələnt/', 'adjective / noun', '{"zh-TW":["等同的；等價物","等同的；等價的"],"en":["equal in value, function, or meaning"]}', '{"prefix":{"text":"equi-","meaning":"equal (等同)"},"root":{"text":"val","meaning":"worth (價值)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"價值等同的。"}', 'equivalent to; equivalent to / the equivalent of / roughly equivalent', '[{"en":"One mile is equivalent to 1.6 kilometers.","zh-TW":"一英里等於1.6公里。"},{"en":"There is no equivalent product on the market.","zh-TW":"市場上沒有同等的產品。"},{"en":"One mile is roughly equivalent to 1.6 kilometers.","zh-TW":"一英里大約等於1.6公里。"},{"en":"There is no equivalent word in English.","zh-TW":"英語中沒有等同的字。"}]', '{"noun":"equivalent/equivalence","adjective":"equivalent"}', NULL, 4, 787),
(788, 'erode', '/ɪˈroʊd/', 'verb', '{"zh-TW":["侵蝕；削弱"],"en":["to gradually wear away or diminish"]}', NULL, 'erode confidence/trust', '[{"en":"Competition has eroded profit margins.","zh-TW":"競爭侵蝕了利潤率。"},{"en":"Public trust in the brand has eroded.","zh-TW":"公眾對品牌的信任已被削弱。"}]', '{"noun":"erosion","verb":"erode"}', NULL, 2, 788),
(789, 'erosion', '/ɪˈroʊʒn/', 'noun', '{"zh-TW":["侵蝕"],"en":["the gradual wearing away of soil or rock"]}', '{"prefix":{"text":"e-","meaning":"away (離去)"},"root":{"text":"ros","meaning":"gnaw (啃蝕)"},"suffix":{"text":"-ion","meaning":"process (過程)"},"logic":"被啃蝕掉的過程，即「侵蝕」。"}', 'soil erosion / coastal erosion', '[{"en":"Soil erosion is a serious environmental problem.","zh-TW":"土壤侵蝕是嚴重的環境問題。"},{"en":"Heavy rain accelerates erosion.","zh-TW":"大雨加速侵蝕。"}]', '{"verb":"erode"}', NULL, 3, 789),
(790, 'error', '/ˈerər/', 'noun', '{"zh-TW":["錯誤；失誤"],"en":["a mistake; something incorrectly done"]}', NULL, 'human/clerical error', '[{"en":"The report contained several errors.","zh-TW":"報告中有幾處錯誤。"},{"en":"The error was caused by a software bug.","zh-TW":"錯誤是由軟體缺陷造成的。"}]', '{"noun":"error","adjective":"erroneous"}', NULL, 2, 790),
(791, 'escape', '/ɪˈskeɪp/', 'verb', '{"zh-TW":["逃脫；避免"],"en":["to get free from","to avoid something unpleasant"]}', NULL, 'escape route / narrow escape', '[{"en":"Know the escape routes in case of fire.","zh-TW":"了解火災時的逃生路線。"},{"en":"We had a narrow escape from the flooding.","zh-TW":"我們險些遭遇洪水。"}]', '{"verb":"escape","noun":"escape"}', NULL, 2, 791),
(792, 'essential', '/ɪˈsenʃəl/', 'adjective', '{"zh-TW":["必要的；基本的","必要的；本質的"],"en":["absolutely necessary; extremely important"]}', '{"root":{"text":"essent","meaning":"being/existence (存在)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與存在本質相關的（不可缺少的）。"}', 'essential for/to; essential skills / essential information / absolutely essential', '[{"en":"Communication skills are essential for this role.","zh-TW":"溝通技能對這個職位是必要的。"},{"en":"It is essential to meet the deadline.","zh-TW":"在截止日期前完成是必要的。"},{"en":"Water is essential for life.","zh-TW":"水是生命所必需的。"},{"en":"Good communication skills are essential for this job.","zh-TW":"良好的溝通能力對這份工作至關重要。"}]', '{"noun":"essential/essentials","adjective":"essential","adverb":"essentially"}', NULL, 3, 792),
(793, 'establish', '/ɪˈstæblɪʃ/', 'verb', '{"zh-TW":["建立；確立","建立；設立"],"en":["to set up; to prove or show","to set up on a firm or permanent basis"]}', '{"prefix":{"text":"e-","meaning":"out (完全)"},"root":{"text":"stabl","meaning":"stable (穩定)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使其穩固確立，即「建立」。"}', 'establish a company/reputation; establish a company / well-established', '[{"en":"The company was established in 1990.","zh-TW":"公司成立於1990年。"},{"en":"We need to establish clear guidelines.","zh-TW":"我們需要建立明確的指導方針。"},{"en":"They established a new policy for remote work.","zh-TW":"他們制定了新的遠端工作政策。"}]', '{"noun":"establishment","verb":"establish","adjective":"established"}', NULL, 3, 793),
(794, 'estimate', '/ˈestɪmeɪt/', 'verb / noun', '{"zh-TW":["估計；預算","估計"],"en":["to roughly calculate; an approximate judgment","to roughly calculate or judge the value of"]}', '{"root":{"text":"estim","meaning":"value (評價)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"做出評價，即「估計」。"}', 'rough/conservative estimate; rough estimate / cost estimate / estimate the cost', '[{"en":"We estimate the cost at $50,000.","zh-TW":"我們估計成本為5萬美元。"},{"en":"The initial estimate was too low.","zh-TW":"最初的估計太低了。"},{"en":"We estimate the project will cost $2 million.","zh-TW":"我們估計這個專案將花費200萬美元。"},{"en":"Can you give me a rough estimate?","zh-TW":"你能給我一個粗略的估計嗎？"}]', '{"noun":"estimate/estimation","verb":"estimate","adjective":"estimated","noun2":"estimation"}', NULL, 3, 794),
(795, 'evaluate', '/ɪˈvæljueɪt/', 'verb', '{"zh-TW":["評估；評價","評估"],"en":["to judge the value or quality of","to judge or determine the significance or value of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"valu","meaning":"value (價值)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"衡量出價值來，即「評估」。"}', 'evaluate performance/options; evaluate performance / evaluate options', '[{"en":"We need to evaluate all options carefully.","zh-TW":"我們需要仔細評估所有選項。"},{"en":"Employee performance is evaluated annually.","zh-TW":"員工績效每年評估一次。"},{"en":"Teachers evaluate student performance regularly.","zh-TW":"老師定期評估學生表現。"},{"en":"We need to evaluate all the options.","zh-TW":"我們需要評估所有選項。"}]', '{"noun":"evaluation","verb":"evaluate"}', NULL, 3, 795),
(796, 'evening', '/ˈiːvnɪŋ/', 'noun', '{"zh-TW":["傍晚；晚上"],"en":["the part of the day between afternoon and night"]}', NULL, 'good evening / evening shift', '[{"en":"Good evening, everyone.","zh-TW":"大家晚上好。"},{"en":"She works the evening shift.","zh-TW":"她上晚班。"}]', '{"noun":"evening"}', NULL, 3, 796),
(797, 'eventually', '/ɪˈventʃuəli/', 'adverb', '{"zh-TW":["最終；終於"],"en":["in the end; after a period of time"]}', NULL, 'eventually lead to', '[{"en":"The negotiations eventually led to an agreement.","zh-TW":"談判最終達成了協議。"},{"en":"He eventually became the CEO.","zh-TW":"他最終成為了執行長。"}]', '{"adjective":"eventual","adverb":"eventually"}', NULL, 4, 797),
(798, 'evidence', '/ˈevɪdəns/', 'noun', '{"zh-TW":["證據；跡象","證據"],"en":["facts or signs showing something is true","facts or information indicating whether something is true"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"vid","meaning":"see (看)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"看得出來的事實，即「證據」。"}', 'provide/present evidence; scientific evidence / evidence suggests / lack of evidence', '[{"en":"There is evidence of improvement in sales.","zh-TW":"有銷售改善的證據。"},{"en":"The data provides evidence of a trend.","zh-TW":"數據提供了趨勢的證據。"},{"en":"There is no evidence to support this claim.","zh-TW":"沒有證據支持這項說法。"},{"en":"The evidence suggests a link between the two.","zh-TW":"證據顯示兩者之間有關聯。"}]', '{"noun":"evidence","adjective":"evident","adverb":"evidently"}', NULL, 3, 798),
(799, 'evolve', '/ɪˈvɑːlv/', 'verb', '{"zh-TW":["進化；發展"],"en":["to develop gradually over time"]}', NULL, 'evolve into/over time', '[{"en":"The company has evolved into a global brand.","zh-TW":"公司已發展成為全球品牌。"},{"en":"Consumer preferences evolve constantly.","zh-TW":"消費者偏好不斷演變。"}]', '{"noun":"evolution","verb":"evolve"}', NULL, 2, 799);